async function list_models(params, userSettings, authorizedResources){
  const apiKey = userSettings.openrouterApiKey;

  // --- STEP 1: FETCH DATA ---
  const res = await fetch('https://openrouter.ai/api/v1/images/models', {
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'HTTP-Referer': window.location.origin || 'https://typingmind.com',
      'X-Title': 'TypingMind Plugin'
    }
  });

  if (!res.ok) throw new Error(`Failed to fetch models: ${res.statusText}`);
  const data = await res.json();

  // --- STEP 2: MAP TO DESIGN SYSTEM CARDS ---
  // We filter out 'null' models (which are placeholders in the API)
  const models = data.data.filter(m => m.id !== null);

  return {
    cards: models.map(model => ({
      type: 'content',
      title: model.name,
      subtitle: model.context_length ? `${Math.floor(model.context_length / 1000)}k Tokens` : '',
      content: model.architecture?.modality?.replace(/^modalities:|\]/g, '').replace(/,/g, ', ') || 'Standard Text Model',
      tags: [
        ...(model.top_provider?.is_preference ? ['Preferred'] : []),
        ...(model.tags || []),
        ...(model.description && model.description.length < 60 ? [model.description] : [])
      ],
      labels: [
        { label: '$/M', color: 'blue', value: `$${(model.pricing?.prompt / 1000000)?.toFixed(2)}` },
        { label: 'Max Context', color: 'purple', value: Math.floor((model.max_tokens || model.context_length)/ 1000) + 'k' }
      ],
      links: [
        { label: 'Details', url: `https://openrouter.ai/${model.slug}` }
      ]
    }))
  };
}

async function get_model_endpoints(params, userSettings, authorizedResources){
  const apiKey = userSettings.openrouterApiKey;
  const modelId = params.modelId;

  if (!modelId) throw new Error('Please specify a Model ID.');

  // --- STEP 1: FETCH ENDPOINTS ---
  const res = await fetch(`https://openrouter.ai/api/v1/images/models/${modelId}/endpoints`, {
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'HTTP-Referer': window.location.origin || 'https://typingmind.com',
      'X-Title': 'TypingMind Plugin'
    }
  });

  if (!res.ok) throw new Error(`Could not find endpoints for ${modelId}.`);
  const data = await res.json();

  // --- STEP 2: RETURN STYLED ENTRIES ---
  return {
    cards: data.data.map(ep => ({
      type: 'list_item',
      title: ep.type,
      content: ep.url, 
      tags: [ep.status === 'available' ? 'Online' : 'Offline'],
      labels: [
        { label: 'Region', color: 'gray', value: ep.region || 'Global' }
      ]
    }))
  };
}
